/**
 * The cover opens a line at a time.
 *
 * Lifted verbatim from the approved page's one script, comments and all. Read
 * them before changing a rule: they record what was measured and what was
 * tried the other way. The IIFE wrapper is kept although a module already
 * gives it: removing it would re-indent the whole file and bury the real
 * history in a diff nobody can read.
 */
import { REDUCED } from './motion-base.js';
/* ── THE COVER OPENS A LINE AT A TIME ─────────────────────────────────────
   The lines are found by measuring, not by guessing: every word is wrapped,
   grouped by the top edge it came to rest on, and the groups become lines. So
   it is right at any width, and it is redone from scratch if it ever needs to
   be.

   It is also temporary. When the opening is over the split comes out and the
   headline goes back to being one run of text -- which is what a resize, a
   copy and a screen reader all want -- and the browser stops holding a
   will-change for a layer nothing will move again. */
(function () {
  var hero = document.querySelector('.hero--print');
  if (!hero) return;
  /* Declining to run means taking the class off, not just leaving it: it is
     inert under reduced motion, but leaving it set would be leaving a claim
     on the page that nothing is going to honour. */
  if (REDUCED.matches) { document.documentElement.classList.remove('intro'); return; }
  var h1 = hero.querySelector('h1');
  if (!h1) return;

  var src = h1.innerHTML;

  /* An ordinary space, and no regular expression.

     Two reasons, and the second is the important one. A space is all that
     separates words here, and the typesetting pass deliberately binds pairs
     like 'public health' with a NO-BREAK space -- so splitting on a plain
     space keeps those pairs whole without being asked, where a whitespace
     class would divide a pair the compositor had joined.

     And this file is emitted from a template literal, which reads escape
     sequences before the browser ever sees them. The whitespace class that
     stood here arrived at the page with its backslashes already eaten,
     matched the whole headline as a single run, and blanked the cover for a
     second and a half. Nothing with a backslash in it belongs in this file
     unless it is doubled, so the safer answer is to need none. */
  var words = h1.textContent.trim().split(' ').filter(Boolean);
  h1.textContent = '';
  var marks = words.map(function (w, i) {
    var sp = document.createElement('span');
    sp.textContent = w;
    sp.style.display = 'inline-block';
    h1.appendChild(sp);
    if (i < words.length - 1) h1.appendChild(document.createTextNode(' '));
    return sp;
  });

  var rows = [], last = null;
  marks.forEach(function (m) {
    var t = Math.round(m.offsetTop);
    if (last === null || Math.abs(t - last) > 4) { rows.push([]); last = t; }
    rows[rows.length - 1].push(m.textContent);
  });

  h1.textContent = '';
  rows.forEach(function (r, i) {
    var outer = document.createElement('span');
    outer.className = 'ln';
    var inner = document.createElement('span');
    inner.className = 'ln-i';
    /* The trailing space is why this reads 'Working with government' and not
       'Working withgovernment' on the clipboard and in the accessibility
       tree. It collapses at the end of a line, so it costs nothing on screen. */
    inner.textContent = r.join(' ') + (i < rows.length - 1 ? ' ' : '');
    inner.style.transitionDelay = (i * 0.09) + 's';
    outer.appendChild(inner);
    h1.appendChild(outer);
  });

  requestAnimationFrame(function () {
    requestAnimationFrame(function () { hero.setAttribute('data-in', ''); });
  });

  setTimeout(function () {
    h1.innerHTML = src;
    document.documentElement.classList.remove('intro');
  }, rows.length * 90 + 1300);
})();

