/**
 * Moving to a section, with the distance eased rather than jumped.
 *
 * Lifted verbatim from the approved page's one script, comments and all. Read
 * them before changing a rule: they record what was measured and what was
 * tried the other way. The IIFE wrapper is kept although a module already
 * gives it: removing it would re-indent the whole file and bury the real
 * history in a diff nobody can read.
 */
import { REDUCED } from './motion-base.js';
/* Moving to a section. The distance is eased here rather than with
   scroll-behavior on the root, for two reasons. That declaration would smooth
   every programmatic scroll on the page, including the ones the measurement
   harness makes just before it reads geometry. And it offers no control over
   duration: the browser scrolls at a fixed velocity, so crossing this document
   to Impact takes about a second and a half of ink fields strobing past, and it
   gets worse every time a section is added.

   Where it lands is NOT decided here. The offset is read back from the
   element's own resolved scroll-margin-top, so CSS stays the single source of
   truth and the click, the pasted fragment and the no-script jump all stop in
   the same place. */
(function () {
  var page = location.pathname.split('/').pop() || 'index.html';
  var run = null;

  function stop() { run = null; }
  ['wheel', 'touchstart', 'keydown'].forEach(function (ev) {
    addEventListener(ev, stop, { passive: true });
  });

  /* covered: a full-screen sheet is over the page right now, so the journey
     is not going to be seen and there is nothing to pace. (No backticks in
     here -- this whole script is itself a template literal, and one would
     end it.) */
  function moveTo(el, covered) {
    var margin = parseFloat(getComputedStyle(el).scrollMarginTop) || 0;
    var max = Math.max(0, document.documentElement.scrollHeight - innerHeight);
    var to = Math.max(0, Math.min(max, el.getBoundingClientRect().top + scrollY - margin));
    var from = scrollY;
    var dist = to - from;
    if (REDUCED.matches || covered || Math.abs(dist) < 2) { scrollTo(0, to); return; }

    /* RISES WITH DISTANCE, AND KEEPS RISING. It used to be capped flat at
       700ms, which meant a jump of a thousand pixels and a jump of twenty
       thousand took the same time -- so the longer the journey the faster it
       had to travel, and the full-page case strobed through six bands in
       four hundred milliseconds. Now the far end of the page gets the time
       it needs:

           800px  560ms    10,000px  1045ms
         3,000px  607ms    20,000px  1670ms

       The ceiling stays under two seconds on purpose. Past that a reader
       stops reading the motion as travel and starts waiting for it to
       finish, and a scroll being waited out is worse than a quick one. */
    var ms = Math.min(1900, Math.max(560, 420 + Math.abs(dist) / 16));
    var t0 = null;
    var me = (run = {});
    function frame(now) {
      if (run !== me) return;            /* the reader took over */
      if (t0 === null) t0 = now;
      var t = Math.min(1, (now - t0) / ms);
      /* Ease in and out: a transit should leave and arrive gently, unlike an
         entrance, which only has to arrive.

         SINE RATHER THAN CUBIC, and the difference is the whole feel of it.
         Both leave and arrive at rest, but a cubic in-out peaks at twice the
         average speed in the middle while sine peaks at 1.57 times. Over a
         long jump that midpoint is exactly where the smear was, so the
         flatter curve is worth more here than anywhere else on the page. */
      var e = 0.5 - Math.cos(Math.PI * t) / 2;
      scrollTo(0, Math.round(from + dist * e));
      if (t < 1) requestAnimationFrame(frame);
      else run = null;
    }
    requestAnimationFrame(frame);
  }

  addEventListener('click', function (e) {
    if (e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
    var a = e.target.closest && e.target.closest('a[href]');
    if (!a || a.target) return;
    var parts = a.getAttribute('href').split('#');
    if (parts.length < 2 || (parts[0] && parts[0] !== page)) return;
    var el = document.getElementById(parts[1]);
    if (!el) return;
    e.preventDefault();

    /* A SAME-PAGE LINK INSIDE THE OPEN MENU HAS TO WAIT FOR IT.
       The menu locks the page with position:fixed while it is open, so a jump
       fired on this click would scroll a document that cannot scroll, and the
       close a moment later would put the reader back where they started. The
       two cancelled exactly, and the link looked broken.

       This used to reach for #navToggle and tell it to close. That control was
       renamed when the flood replaced the stock burger, so the line found null
       and did nothing: dead code that read as a safeguard. The menu closes
       itself on its own beat now -- long enough for the chosen word to show
       gold -- and says so when it has let go of the page.

       The ink is still draining while the travel runs, so what the reveal
       shows is the destination arriving. */
    var fld = document.getElementById('fldMenu');
    if (fld && fld.hasAttribute('data-live')) {
      /* THE SHEET CARRIES IT. menushut fires the instant the page is
         scrollable again, which is also the instant the ink STARTS draining
         -- it has half a second still to go and the screen is entirely navy.
         So the page is put at its destination now, under cover, and the
         drain reveals the section already in place. The reader never sees
         the journey, which is the only way a twenty-thousand-pixel one can
         be anything but a strobe. */
      fld.addEventListener('menushut', function once() {
        fld.removeEventListener('menushut', once);
        moveTo(el, true);
      });
    } else {
      moveTo(el);
    }
    if (history.replaceState) history.replaceState(null, '', '#' + parts[1]);
    /* Keyboard readers have to arrive inside the section, not back at the top
       of the document — and without being scrolled a second time by the focus. */
    el.setAttribute('tabindex', '-1');
    el.focus({ preventScroll: true });
  });

})();

