/**
 * The margin index: this document's table of contents, tracking where the
 * reader is.
 *
 * Lifted verbatim from the approved page's one script, comments and all. Read
 * them before changing a rule: they record what was measured and what was
 * tried the other way. The IIFE wrapper is kept although a module already
 * gives it: removing it would re-indent the whole file and bury the real
 * history in a diff nobody can read.
 */
/* The navigation is this document's table of contents. Each section names the
   tab that owns it — About owns nine of them — and the tab for whatever is
   under the reading line is marked current. The line sits a third of the way
   down rather than at the header's edge: the section you are reading is the one
   under your eyes, not the one whose first pixel has just cleared the bar. */
(function () {
  var links = [].slice.call(
    document.querySelectorAll('.nav-links a[data-tab], .nav-panel-links a[data-tab]')
  );
  /* A link the build already marked as the current PAGE keeps that mark: a page
     you are on does not stop being the page you are on because you scrolled. */
  var owned = links.filter(function (a) { return a.getAttribute('aria-current') !== 'page'; });
  var secs = [].slice.call(document.querySelectorAll('.band[data-tab]'));
  if (!owned.length || !secs.length) return;

  /* The marker in the margin reads the same value the underline does, so the
     two can never disagree about where the reader is. */
  var grounds = [].slice.call(document.querySelectorAll('[data-nav]'));
  var mark = document.getElementById('partMark');
  var markName = mark && mark.querySelector('.mark-name');
  var markBar = mark && mark.querySelector('.mark-track i');
  var markList = mark && mark.querySelector('.mark-list');
  var shown = null;
  var shownAt = -1;

  /* The chapters of a part, in order, with consecutive repeats collapsed — the
     programme page has four sections called Results in a row, and a scrubber
     that ticks four times without the word changing reads as a fault. */
  function chaptersOf(tab) {
    var out = [];
    for (var i = 0; i < secs.length; i++) {
      if (secs[i].getAttribute('data-tab') !== tab) continue;
      var c = secs[i].getAttribute('data-chapter');
      if (!c) continue;
      if (out.length && out[out.length - 1].name === c) { out[out.length - 1].els.push(secs[i]); continue; }
      out.push({ name: c, els: [secs[i]] });
    }
    return out;
  }

  var chapters = [];
  function buildList(tab) {
    chapters = chaptersOf(tab);
    markList.textContent = '';
    for (var i = 0; i < chapters.length; i++) {
      var li = document.createElement('li');
      /* An anchor to the chapter's first section. The page's own click handler
         takes it from there: it eases the distance, reads where to stop from
         the section's resolved scroll-margin-top, and focuses it on arrival. */
      var id = chapters[i].els[0].id;
      if (id) {
        var a = document.createElement('a');
        a.setAttribute('href', '#' + id);
        a.textContent = chapters[i].name;
        li.appendChild(a);
      } else {
        li.textContent = chapters[i].name;
      }
      markList.appendChild(li);
    }
    shownAt = -1;
  }

  var queued = false;
  function spy() {
    queued = false;
    var line = innerHeight * 0.34;
    var tab = null;
    var here = null;
    for (var i = 0; i < secs.length; i++) {
      var r = secs[i].getBoundingClientRect();
      if (r.top <= line && r.bottom > line) { tab = secs[i].getAttribute('data-tab'); here = secs[i]; break; }
    }

    /* PAST THE LAST BAND, THE MARKER HOLDS ITS LAST PART RATHER THAN BLINKING
       OUT. The footer belongs to no part, so once it is deep enough to reach
       the reading line -- which it now is, because it runs to the foot of the
       window -- nothing matched and the index vanished on the final screen.
       A reader down there is still after Get Involved, not nowhere.

       Only BELOW the last band. Above the first one there genuinely is no
       part yet, and the marker is right to stay away until the page has one
       to name. */
    if (!tab && secs.length) {
      var last = secs[secs.length - 1];
      if (last.getBoundingClientRect().bottom <= line) {
        tab = last.getAttribute('data-tab');
        here = last;
      }
    }
    owned.forEach(function (a) {
      if (a.getAttribute('data-tab') === tab) a.setAttribute('aria-current', 'true');
      else if (a.getAttribute('aria-current') === 'true') a.removeAttribute('aria-current');
    });

    if (!mark) return;
    if (!tab) {
      if (shown !== null) { mark.removeAttribute('data-on'); mark.hidden = true; shown = null; }
      return;
    }
    if (tab !== shown) {
      markName.textContent = tab;
      /* Named for the part it lists, so a screen reader reader meets a section
         index for About rather than a second unexplained copy of the site
         navigation. That duplication was the reason this used to be
         aria-hidden. */
      mark.setAttribute('aria-label', tab + ' — sections');
      buildList(tab);
      mark.hidden = false;
      mark.setAttribute('data-on', '');
      shown = tab;
    }

    /* Which chapter of that part is on screen, and slide the list so it sits on
       the row beside the part's name. One row of travel, always, whatever the
       words are — the row height is fixed. */
    var at = 0;
    for (var c = 0; c < chapters.length; c++) {
      if (chapters[c].els.indexOf(here) > -1) { at = c; break; }
    }
    if (at !== shownAt) {
      var row = parseFloat(getComputedStyle(mark.querySelector('.mark-win')).getPropertyValue('--row')) || 22;
      markList.style.setProperty('--y', (1 - at) * row + 'px');
      for (var d = 0; d < markList.children.length; d++) {
        if (d === at) markList.children[d].setAttribute('data-on', '');
        else markList.children[d].removeAttribute('data-on');
      }
      shownAt = at;
    }

    /* Which grounds the marker's own box is standing on. One means there is an
       ink that is correct; two means a field edge is crossing the label and
       there is not, so it prints nothing until the edge has passed. */
    var mr = mark.getBoundingClientRect();
    var on = [];
    for (var g = 0; g < grounds.length; g++) {
      var gr = grounds[g].getBoundingClientRect();
      if (gr.bottom > mr.top + 1 && gr.top < mr.bottom - 1) on.push(grounds[g]);
    }
    /* ONE FIELD, NOT ONE ELEMENT. What this rule guards against is a FIELD
       EDGE crossing the label -- a change of ground under it, for which no
       single ink is correct. A field edge is a change of background, so that
       is what is compared.

       Counting elements made the marker vanish on the last screen, where its
       box spans the join between the navy Get in touch band and the navy
       footer. Two elements, one ground, and nothing wrong with printing
       across them. Comparing text colour instead was no better: those two do
       differ, at 1.0 and 0.86 white, which is a difference nobody can see on
       the same navy and not what the rule is for. */
    var field = null, same = on.length > 0;
    for (var q = 0; q < on.length; q++) {
      var key = getComputedStyle(on[q]).backgroundColor;
      if (field === null) field = key;
      else if (key !== field) { same = false; break; }
    }
    if (same) {
      mark.removeAttribute('data-straddle');
      /* The band's own primary ink, not a light/dark approximation of it: on
         gold every other mark is the dark brown that field uses, and a navy
         marker there is legible but borrowed. The unread rows take that band's
         resting ink, the field's own measured value, so they are dim by a
         figure measured on that ground rather than by an opacity guess. */
      var cs = getComputedStyle(on[0]);
      mark.style.color = cs.color;
      mark.style.setProperty('--mark-rest', cs.getPropertyValue('--read-rest') || cs.color);
    } else {
      mark.setAttribute('data-straddle', '');
    }
    /* How far through this part the reader is: the run of consecutive sections
       that share the tab, measured end to end. */
    var first = here;
    var last = here;
    var k = secs.indexOf(here);
    while (k > 0 && secs[k - 1].getAttribute('data-tab') === tab) { first = secs[--k]; }
    k = secs.indexOf(here);
    while (k < secs.length - 1 && secs[k + 1].getAttribute('data-tab') === tab) { last = secs[++k]; }
    var top = first.getBoundingClientRect().top + scrollY;
    var bottom = last.getBoundingClientRect().bottom + scrollY;
    var span = Math.max(1, bottom - top - innerHeight * 0.34);
    var p = Math.max(0, Math.min(1, (scrollY + innerHeight * 0.34 - top) / span));
    markBar.style.setProperty('--p', p.toFixed(4));
  }
  addEventListener('scroll', function () {
    if (queued) return;
    queued = true;
    requestAnimationFrame(spy);
  }, { passive: true });
  addEventListener('resize', spy, { passive: true });
  spy();
})();

