/**
 * Our history: the register under the portfolio cards.
 *
 * Added on 16 November 2026, after the port; it is not lifted from the
 * approved page. It is written the way the lifted modules are, a body that
 * closes over REDUCED, so that the frozen reference can carry the same body
 * in its one inline script and tests/parity/assembly.mjs can hold the two to
 * the same hash. Its departure is recorded in tests/parity/extracted.sha256.json.
 *
 * It runs after overview.js because it opens the portfolio overviews that
 * module wires up.
 */
import { REDUCED } from './motion-base.js';
/* ---------------------------------------------------------------------
   Our history: the register. Filter it by portfolio or by place, open a
   milestone, and go up to the portfolio that carries that work today. */
(function () {
  var root = document.querySelector('[data-rg]');
  if (!root) return;
  var list = root.querySelector('.rg-list');
  var tools = root.querySelector('.rg-tools');
  var items = [].slice.call(root.querySelectorAll('.rg-i'));
  var chips = [].slice.call(root.querySelectorAll('.rg-f button'));
  var sel = root.querySelector('.rg-sel select');
  var sort = root.querySelector('.rg-sort');
  var count = root.querySelector('.rg-count');
  var none = root.querySelector('.rg-none');
  if (!list || !tools || !items.length || !chips.length || !sel || !sort || !count || !none) return;

  /* The no-script state is every milestone open and no controls. Close the
     rows, and only now draw the controls that open and filter them. */
  items.forEach(function (li) {
    li.querySelector('.rg-row').setAttribute('aria-expanded', 'false');
  });
  root.classList.add('rg--on');
  tools.hidden = false;
  count.hidden = false;

  var area = '';
  var where = '';
  function apply() {
    var shown = 0;
    items.forEach(function (li) {
      var keys = li.getAttribute('data-where').split('|');
      var ok = (!area || li.getAttribute('data-area') === area) &&
        (!where || keys.indexOf(where) >= 0);
      li.hidden = !ok;
      if (ok) shown++;
    });
    var parts = [];
    chips.forEach(function (c) {
      var on = c.getAttribute('data-area') === area;
      c.setAttribute('aria-pressed', String(on));
      if (on && area) parts.push(c.querySelector('span').textContent);
    });
    if (where) parts.push(sel.options[sel.selectedIndex].getAttribute('data-name'));
    /* The sentence is the content's, with its two slots filled. */
    count.textContent = root.getAttribute('data-count')
      .replace('{shown}', String(shown))
      .replace('{total}', String(items.length)) +
      (parts.length ? ': ' + parts.join(', ') : '');
    none.hidden = shown > 0;
    list.hidden = shown === 0;
  }

  chips.forEach(function (c) {
    c.addEventListener('click', function () {
      area = c.getAttribute('data-area');
      apply();
    });
  });
  sel.addEventListener('change', function () {
    where = sel.value;
    apply();
  });
  root.querySelector('.rg-clear').addEventListener('click', function () {
    area = '';
    where = '';
    sel.value = '';
    apply();
    chips[0].focus();
  });

  /* One label, and the pressed state says whether it is in force. A label
     that flipped to "Oldest first" while also reporting pressed would read,
     to a screen reader, as the opposite of what the list shows. */
  sort.addEventListener('click', function () {
    var newest = sort.getAttribute('aria-pressed') !== 'true';
    sort.setAttribute('aria-pressed', String(newest));
    (newest ? items.slice().reverse() : items).forEach(function (li) {
      list.appendChild(li);
    });
  });

  items.forEach(function (li) {
    var row = li.querySelector('.rg-row');
    row.addEventListener('click', function () {
      var open = !li.classList.contains('is-open');
      li.classList.toggle('is-open', open);
      row.setAttribute('aria-expanded', String(open));
    });
  });

  /* Up to the portfolio that carries the work now, with its overview open.
     The link's own address is that overview, which is where a reader without
     script lands: for them every overview is already open. */
  [].slice.call(root.querySelectorAll('.rg-go')).forEach(function (a) {
    a.addEventListener('click', function (e) {
      var code = a.getAttribute('data-code');
      var btn = document.getElementById('ovb-' + code);
      var card = btn && btn.closest('.acard');
      if (!card || btn.hidden) return;
      e.preventDefault();

      /* Open first, measure after. Opening this overview shuts any other, and
         one open above this card would move it after it had been measured.
         overview.js gives the opened panel focus; an overview that was open
         already is given it here, so a keyboard reader lands in it either way. */
      if (btn.getAttribute('aria-expanded') !== 'true') {
        btn.click();
      } else {
        var panel = document.getElementById('ov-' + code);
        if (panel) panel.focus({ preventScroll: true });
      }

      /* Where it stops is the page's anchor offset, read back from the card's
         own button, which carries an id and so the [id] scroll margin. */
      var margin = parseFloat(getComputedStyle(btn).scrollMarginTop) || 0;
      var top = card.getBoundingClientRect().top + scrollY - margin;
      scrollTo({ top: Math.max(0, top), behavior: REDUCED.matches ? 'auto' : 'smooth' });

      card.classList.remove('rg-here');
      void card.offsetWidth;
      card.classList.add('rg-here');
    });
  });

  apply();
})();
