/**
 * Our areas of work: the portfolio overview opens below its row.
 *
 * Lifted verbatim from the approved page's one script, comments and all. Read
 * them before changing a rule: they record what was measured and what was
 * tried the other way. The IIFE wrapper is kept although a module already
 * gives it: removing it would re-indent the whole file and bury the real
 * history in a diff nobody can read.
 */
/* ---------------------------------------------------------------------
   Our areas of work: the portfolio overview opens below its row.
   Chosen from six placements built and compared side by side; this is the
   one that keeps the grid of prints intact. */
(function () {
  var grid = document.querySelector('.acards');
  if (!grid) return;
  var cards = [].slice.call(grid.querySelectorAll('.acard'));
  var panels = [].slice.call(grid.querySelectorAll('.acard-panel'));
  if (!cards.length || cards.length !== panels.length) return;

  /* The no-script state is every overview open. Close them, and only now
     reveal the controls that close and open them. */
  panels.forEach(function (p) { p.hidden = true; });
  var open = -1;

  /* Where the gold tab goes. Measured against the laid-out boxes rather than
     computed from an index, for the same reason the row is: these cards are
     not all the same width. Both rectangles are border boxes and the tab is
     positioned against the panel's padding box, which with no border on the
     panel is the same edge. */
  function mark() {
    if (open < 0) return;
    var c = cards[open].getBoundingClientRect();
    var p = panels[open].getBoundingClientRect();
    panels[open].style.setProperty('--mark-x', (c.left - p.left) + 'px');
    panels[open].style.setProperty('--mark-w', c.width + 'px');
  }

  function shut() {
    if (open < 0) return;
    cards[open].removeAttribute('data-open');
    cards[open].querySelector('.acard-go').setAttribute('aria-expanded', 'false');
    panels[open].hidden = true;
    open = -1;
  }

  cards.forEach(function (card, i) {
    var go = card.querySelector('.acard-go');
    if (!go) return;
    go.hidden = false;
    go.addEventListener('click', function () {
      var was = open;
      shut();
      if (was === i) return;

      /* Which cards share a row with this one. Measured, because the cards
         are not all the same width and an index cannot tell you. */
      var top = card.offsetTop;
      var last = i;
      for (var k = 0; k < cards.length; k++) {
        if (Math.abs(cards[k].offsetTop - top) <= 2) last = k;
      }
      cards.forEach(function (c, k) { c.style.order = (k + 1) * 10; });
      panels[i].style.order = (last + 1) * 10 + 5;

      open = i;
      card.setAttribute('data-open', '');
      go.setAttribute('aria-expanded', 'true');
      panels[i].hidden = false;
      mark();
      /* The panel takes focus so a keyboard reader lands in what just opened
         rather than back at the top of the grid. */
      panels[i].focus({ preventScroll: true });
    });
  });

  /* A row can change which cards it holds when the grid reflows, so an open
     drawer has to be re-placed rather than left where it was. */
  var queued = false;
  addEventListener('resize', function () {
    if (open < 0 || queued) return;
    queued = true;
    requestAnimationFrame(function () {
      queued = false;
      if (open < 0) return;
      var top = cards[open].offsetTop, last = open;
      for (var k = 0; k < cards.length; k++) {
        if (Math.abs(cards[k].offsetTop - top) <= 2) last = k;
      }
      panels[open].style.order = (last + 1) * 10 + 5;
      /* After the re-place, not before: the card may have moved to a different
         row and the tab has to follow it there. */
      mark();
    });
  }, { passive: true });
})();

