/**
 * Our journey, ruled as it is scrolled.
 *
 * Lifted verbatim from the approved page's one script, comments and all. Read
 * them before changing a rule: they record what was measured and what was
 * tried the other way. The IIFE wrapper is kept although a module already
 * gives it: removing it would re-indent the whole file and bury the real
 * history in a diff nobody can read.
 */
import { REDUCED } from './motion-base.js';
/* Our journey is ruled as you scroll it.

   Each rule's width is a function of where it sits in the window: nothing at
   the bottom edge, complete by the time it is above the reading line. It
   grows while you move and holds where you leave it.

   BOUND TO SCROLL POSITION, unlike everything else here. The distinction is
   the one this page's motion turns on: the lift, the cover and the cue are
   ARRIVING, and an arrival stopped halfway is just broken, so they run on a
   clock once triggered. A rule being drawn is not arriving, it is tracking,
   and half-drawn is the correct state for a line you are halfway to.

   THE BAND IS 37vh, from 0.95 to 0.58. Measured against the entries rather
   than chosen: they run about 300px at this width, so a rule finishes at
   roughly the moment the next one enters from the bottom, and there is one
   line drawing for as long as the reader keeps moving. Widen it and two are
   always in flight, which stops reading as ruling and starts reading as a
   loading bar.

   Written to the inline transform rather than a class, because the value is
   continuous; rounded to three places so a frame that has not moved the line
   by a tenth of a pixel does no work at all. */
(function () {
  var rules = [].slice.call(document.querySelectorAll('.spine-rule'));
  if (!rules.length || REDUCED.matches) return;

  var at = rules.map(function () { return -1; });

  function draw() {
    queued = false;
    var start = innerHeight * 0.95;
    var end = innerHeight * 0.58;
    var span = Math.max(1, start - end);
    for (var i = 0; i < rules.length; i++) {
      var top = rules[i].getBoundingClientRect().top;
      var p = Math.max(0, Math.min(1, (start - top) / span));
      p = Math.round(p * 1000) / 1000;
      if (p === at[i]) continue;
      at[i] = p;
      rules[i].style.transform = 'scaleX(' + p + ')';
    }
  }

  var queued = false;
  function ask() {
    if (queued) return;
    queued = true;
    requestAnimationFrame(draw);
  }
  addEventListener('scroll', ask, { passive: true });
  /* Resize changes the band itself, not just the positions in it. */
  addEventListener('resize', ask, { passive: true });
  draw();
})();

