/**
 * The purpose band, in four beats.
 *
 * Lifted verbatim from the approved page's one script, comments and all. Read
 * them before changing a rule: they record what was measured and what was
 * tried the other way. The IIFE wrapper is kept although a module already
 * gives it: removing it would re-indent the whole file and bury the real
 * history in a diff nobody can read.
 */
import { onReveal } from './motion-base.js';
/* The purpose band, in four beats.

   Each part gets its own threshold, deeper than the last, so the gaps between
   beats are wider than the gaps between the elements. Without that the
   sequence would be whatever the spacing happened to produce, which on a tall
   window is nearly all at once. */
(function () {
  function stage(sel, pct) {
    onReveal(sel, function (el) {
      el.classList.add('in');
      /* A label belongs to what it labels, so the eyebrow arrives with its
         statement rather than a beat early for sitting higher on the page. */
      var k = el.previousElementSibling;
      if (k && k.classList.contains('creed-k')) k.classList.add('in');
    }, { rootMargin: '0px 0px -' + pct + '% 0px' });
  }
  stage('#purpose .creed-v', 18);
  stage('#purpose .creed-m', 26);
  stage('#purpose .read', 32);
})();

