/**
 * The header: the progress rule, and the theme each band hands it as it passes.
 *
 * Lifted verbatim from the approved page's one script, comments and all. Read
 * them before changing a rule: they record what was measured and what was
 * tried the other way. The IIFE wrapper is kept although a module already
 * gives it: removing it would re-indent the whole file and bury the real
 * history in a diff nobody can read.
 */

(function () {
  const nav = document.getElementById('nav');
  if (!nav) return;
  const bar = nav.querySelector('.nav-progress i');
  const grounds = [].slice.call(document.querySelectorAll('[data-nav]'));
  const root = document.documentElement;
  /* Measured in the resting state only. The capsule is shorter once scrolled,
     and every hero pads itself by calc(var(--nav-h) + ...) — so measuring it
     at any moment would make every hero's top padding jump the instant the
     reader moved. */
  function measure() {
    const was = nav.hasAttribute('data-scrolled');
    if (was) nav.removeAttribute('data-scrolled');
    root.style.setProperty('--nav-h', nav.offsetHeight + 'px');
    if (was) nav.setAttribute('data-scrolled', '');
  }
  measure();

  let queued = false;
  function read() {
    queued = false;
    /* Ten pixels, as in the reference: enough that the capsule does not
       flicker on a trackpad twitch, little enough that it reads as a response
       to the reader rather than as a delay. */
    if (scrollY > 10) nav.setAttribute('data-scrolled', '');
    else nav.removeAttribute('data-scrolled');
    if (bar) {
      const max = document.documentElement.scrollHeight - innerHeight;
      bar.style.width = (max > 0 ? Math.min(100, (scrollY / max) * 100) : 0) + '%';
    }
    /* Theme comes from whichever declared ground the bar is currently over,
       measured just below its own bottom edge. */
    if (grounds.length) {
      const line = nav.offsetHeight * 0.75;
      let theme = nav.dataset.fallbackTheme || 'dark';
      for (let i = 0; i < grounds.length; i++) {
        const r = grounds[i].getBoundingClientRect();
        if (r.top <= line && r.bottom > line) theme = grounds[i].dataset.nav;
      }
      if (nav.dataset.theme !== theme) nav.dataset.theme = theme;
    }
  }
  addEventListener('scroll', function () {
    if (queued) return;
    queued = true;
    requestAnimationFrame(read);
  }, { passive: true });
  addEventListener('resize', function () {
    measure();
    read();
  }, { passive: true });
  read();

  const btn = document.getElementById('navToggle');
  const panel = document.getElementById('navPanel');
  if (btn && panel) {
    /* The overlay covers the page, so the page behind it must not scroll. The
       previous value is restored rather than cleared, in case anything else
       ever sets it. */
    let priorOverflow = '';
    function setOpen(open) {
      if (open) {
        priorOverflow = document.body.style.overflow;
        panel.setAttribute('data-open', '');
        document.body.style.overflow = 'hidden';
      } else {
        panel.removeAttribute('data-open');
        document.body.style.overflow = priorOverflow;
      }
      btn.setAttribute('aria-expanded', String(open));
      if (open) nav.setAttribute('data-panel', '');
      else nav.removeAttribute('data-panel');
      /* The panel's ink follows the header's, so the overlay is never the
         wrong theme for the ground the bar is sitting on. */
      panel.dataset.theme = nav.dataset.theme || 'dark';
    }
    btn.addEventListener('click', function () {
      setOpen(!panel.hasAttribute('data-open'));
    });
    /* A full-screen overlay that only the button can close is a trap. */
    addEventListener('keydown', function (e) {
      if (e.key === 'Escape' && panel.hasAttribute('data-open')) {
        setOpen(false);
        btn.focus();
      }
    });
    /* Following a link inside it leaves the page scroll-locked otherwise. */
    panel.addEventListener('click', function (e) {
      if (e.target.closest('a')) setOpen(false);
    });
    /* Crossing the collapse with the panel open would leave the body locked
       against a menu that is no longer displayed. */
    addEventListener('resize', function () {
      if (innerWidth >= 1040 && panel.hasAttribute('data-open')) setOpen(false);
    }, { passive: true });
  }
})();


